def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find full separator rows and columns.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))]
    # Keep only lines whose value is not the background.
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(row.count(x) for row in grid))
    sep_rows = [r for r in sep_rows if grid[r][0] != bg]
    sep_cols = [c for c in sep_cols if grid[0][c] != bg]

    rbounds = [-1] + sep_rows + [h]
    cbounds = [-1] + sep_cols + [w]
    regions = []
    for i in range(len(rbounds) - 1):
        for j in range(len(cbounds) - 1):
            r0, r1 = rbounds[i] + 1, rbounds[i + 1]
            c0, c1 = cbounds[j] + 1, cbounds[j + 1]
            if r0 < r1 and c0 < c1:
                regions.append((r0, r1, c0, c1))

    # Use the region containing the most non-background cells as the template.
    template = max(
        regions,
        key=lambda z: sum(
            grid[r][c] != bg
            for r in range(z[0], z[1])
            for c in range(z[2], z[3])
        ),
    )
    r0, r1, c0, c1 = template
    out = [row[:] for row in grid]
    for a, b, x, y in regions:
        for r in range(a, b):
            for c in range(x, y):
                sr, sc = r0 + (r - a), c0 + (c - x)
                if sr < r1 and sc < c1:
                    out[r][c] = grid[sr][sc]
    return out
